import javax.microedition.m3g.*;import javax.microedition.lcdui.*;import crimson.M3GPlatform;
public class M3GSpanCheck {
 static Graphics3D g=Graphics3D.getInstance();static VertexBuffer vb;static TriangleStripArray ix;static Camera cam;static Texture2D tex;static Appearance app;
 static int[] render(boolean fast,int fogMode,int mode,int tm,int perspective)throws Exception{M3GPlatform.nativeRaster=fast;M3GPlatform.m3gPerspectiveCorrectionMode=perspective;Image im=Image.createImage(64,64);app.setTexture(0,tm<0?null:tex);tex.setBlending(tm==0?Texture2D.FUNC_REPLACE:Texture2D.FUNC_MODULATE);CompositingMode cm=new CompositingMode();cm.setBlending(mode);cm.setAlphaThreshold(.1f);app.setCompositingMode(cm);Fog fog=null;if(fogMode!=0){fog=new Fog();fog.setMode(fogMode);fog.setColor(0x817257);fog.setLinear(1,8);fog.setDensity(.1f);}app.setFog(fog);g.bindTarget(im.getGraphics(),true,Graphics3D.TRUE_COLOR);g.setCamera(cam,null);Background bg=new Background();bg.setColor(0xff3f88a0);g.clear(bg);g.render(vb,ix,app,null);g.releaseTarget();int[] out=new int[4096];im.getRGB(out,0,64,0,0,64,64);return out;}
 public static void main(String[]args)throws Exception{
 cam=new Camera();cam.setPerspective(60,1,1,20);vb=new VertexBuffer();VertexArray pos=new VertexArray(4,3,2);pos.set(0,4,new short[]{-1,-1,-3,1,-1,-4,-1,1,-2,1,1,-3});vb.setPositions(pos,1,null);VertexArray color=new VertexArray(4,4,1);color.set(0,4,new byte[]{(byte)255,80,60,(byte)200,40,(byte)255,80,(byte)255,60,80,(byte)255,(byte)170,(byte)255,(byte)255,(byte)255,(byte)255});vb.setColors(color);VertexArray uv=new VertexArray(4,2,2);uv.set(0,4,new short[]{-1,0,3,0,-1,3,3,3});vb.setTexCoords(0,uv,1,null);ix=new TriangleStripArray(new int[]{0,1,2,3},new int[]{4});app=new Appearance();PolygonMode pm=new PolygonMode();pm.setCulling(PolygonMode.CULL_NONE);app.setPolygonMode(pm);byte[] data=new byte[4*4*4];for(int i=0;i<16;i++){data[i*4]=(byte)(i*15);data[i*4+1]=(byte)180;data[i*4+2]=(byte)(255-i*15);data[i*4+3]=(byte)(i%3==0?60:255);}tex=new Texture2D(new Image2D(Image2D.RGBA,4,4,data));tex.setFiltering(Texture2D.FILTER_BASE_LEVEL,Texture2D.FILTER_NEAREST);tex.setWrapping(Texture2D.WRAP_REPEAT,Texture2D.WRAP_CLAMP);
 int tests=0,rounding=0;long slow=0,quick=0;int[] modes={CompositingMode.REPLACE,CompositingMode.ALPHA,CompositingMode.ALPHA_ADD,CompositingMode.MODULATE,CompositingMode.MODULATE_X2};for(int perspective=0;perspective<2;perspective++)for(int fog:new int[]{0,Fog.LINEAR,Fog.EXPONENTIAL})for(int mode:modes)for(int t=-1;t<2;t++){long start=System.currentTimeMillis();int[] expected=render(false,fog,mode,t,perspective);slow+=System.currentTimeMillis()-start;start=System.currentTimeMillis();int[] actual=render(true,fog,mode,t,perspective);quick+=System.currentTimeMillis()-start;for(int i=0;i<actual.length;i++)if(actual[i]!=expected[i]){int max=0;for(int shift=0;shift<32;shift+=8)max=Math.max(max,Math.abs((actual[i]>>>shift&255)-(expected[i]>>>shift&255)));if(max<=(mode==CompositingMode.MODULATE_X2?2:1)&&fog==Fog.EXPONENTIAL){rounding++;continue;}throw new Exception("span mismatch fog="+fog+" mode="+mode+" tex="+t+" persp="+perspective+" pixel="+i+" expected="+Integer.toHexString(expected[i])+" actual="+Integer.toHexString(actual[i]));}tests++;}
 if(M3GPlatform.nativeSpans==0)throw new Exception("native path unused");System.out.println("M3G_SPAN_PASS cases="+tests+" Java_ms="+slow+" native_ms="+quick+" rounding_pixels="+rounding+" spans="+M3GPlatform.nativeSpans);
 }
}
